class Solution {
    private fun occurrences(text:String,pattern:String):List<Int>{
        val prefix=IntArray(pattern.length);
        var matched=0;
        for(i in 1 until pattern.length){
            while(matched>0&&pattern[i]!=pattern[matched])matched=prefix[matched-1];
            if(pattern[i]==pattern[matched])matched++;
            prefix[i]=matched
        };
        val positions=ArrayList<Int>();
        matched=0;
        for(i in text.indices){
            while(matched>0&&text[i]!=pattern[matched])matched=prefix[matched-1];
            if(text[i]==pattern[matched])matched++;
            if(matched==pattern.length){
                positions.add(i-pattern.length+1);
                matched=prefix[matched-1]
            }
        };
        return positions
    };
    fun beautifulIndices(s:String,a:String,b:String,k:Int):List<Int>{
        val first=occurrences(s,a);
        val second=occurrences(s,b);
        val answer=ArrayList<Int>();
        var pointer=0;
        for(index in first){
            while(pointer<second.size&&second[pointer]<index-k)pointer++;
            if(pointer<second.size&&second[pointer]<=index+k)answer.add(index)
        };
        return answer
    }
}

